import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

base='http://localhost:8080'
token=None

def get_token():
    global token
    req=urllib.request.Request(base+'/token', method='POST')
    with urllib.request.urlopen(req, timeout=10) as r:
        token=[REDACTED_SECRET]'token']

def request(path, method='GET'):
    global token
    if token is None: get_token()
    for attempt in range(20):
        req=urllib.request.Request(base+path, method=method, headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req, timeout=10) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode('utf-8','replace')
            if e.code in (401,403):
                get_token(); continue
            if e.code in (429, 503):
                wait=None
                for k,v in e.headers.items():
                    if k.lower() in ('retry-after','x-retry-after'):
                        try: wait=float(v); break
                        except: pass
                try:
                    obj=json.loads(body)
                    for k in ('retry_after','retryAfter','wait_seconds','wait'):
                        if k in obj: wait=float(obj[k]); break
                except: pass
                if wait is None: wait=1.0
                time.sleep(wait); continue
            raise RuntimeError(f'{path} HTTP {e.code}: {body}')
        except (urllib.error.URLError, TimeoutError):
            time.sleep(min(2**attempt,10)); continue
    raise RuntimeError('too many retries '+path)

seen=set(); duplicates=0; orders=[]; page=1
while True:
    data=request('/orders?page='+str(page))
    items=data['items']
    for o in items:
        if o['id'] in seen:
            duplicates += 1
        else:
            seen.add(o['id']); orders.append(o)
    if not data.get('next'): break
    page += 1

customers={}
for o in orders:
    cid=o['customer_id']
    if cid not in customers: customers[cid]=request('/customers/'+str(cid))

start=datetime(2025,3,1,tzinfo=timezone.utc)
end=datetime(2025,6,1,tzinfo=timezone.utc)
regions={k:0 for k in ('north','south','east','west')}
count=0
for o in orders:
    if o['status'] "'!= '"'shipped': continue
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if not (start <= dt < end): continue
    c=customers[o['customer_id']]
    # exact integer half-up: amount * (100-discount) / 100
    cents=(Decimal(o['amount_cents'])*(Decimal(100-c['discount_pct']))/Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    regions[c['region']] += int(cents); count += 1
result={'total_cents':sum(regions.values()),'order_count':count,'duplicates_skipped':duplicates,'by_region':regions}
print(json.dumps({'pages':page,'unique_listings':len(seen),'customers':len(customers),'result':result}, sort_keys=True))
